import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const a = second.split(" ").map(Number);

// 1 回の走査で最大と最小を同時に求める
let max = a[0];
let min = a[0];
for (const x of a) {
  if (x > max) max = x;
  if (x < min) min = x;
}
console.log(max - min);
